    return true;
  }
  function jx() {
    if (!ENV_JAVA) throw new Error('阅读 Java 扩展未绑定');
    return ENV_JAVA;
  }
  function srcObj() {
    if (!ENV_SOURCE) throw new Error('阅读书源对象未绑定');
    return ENV_SOURCE;
  }
  var CFG = {
    appVersion: '3.1.5',
    merchantId: 0,
    siteId: 1,
    bases: [
      'http://114.67.83.0:54726/',
