function xyLoginMap(){
  try{if(typeof result==='object'&&result)return result}catch(e){}
  try{return source.getLoginInfoMap()||{}}catch(e){return {}}
}
function xySay(v,longMode){try{if(longMode&&java.longToast)java.longToast(String(v));else java.toast(String(v))}catch(e){}}
function xyRequireAdLogin(){if(!XY.token())throw new Error('请先登录星愿瓶账号')}
function xyPendingAd(){try{return String(source.get('xy_ad_guanggaoid')||'').trim()}catch(e){return ''}}
function xyClearAd(){source.put('xy_ad_guanggaoid','');source.put('xy_ad_trans_id','')}
function xySaveSource(){XY.setEnv(java,source);var m=xyLoginMap();var s=XY.saveSearchSource(m['搜索来源']);xySay('搜索来源已切换为：'+s,false)}
function xyLogin(){
  XY.setEnv(java,source);var m=xyLoginMap();XY.saveSearchSource(m['搜索来源']);
  try{XY.login(m['账号'],m['密码']);xySay('星愿瓶登录成功\n搜索来源：'+XY.searchSource(),true)}
  catch(e){xySay('登录失败：'+String(e.message||e),true);throw e}
}
function xyAdRules(){
  XY.setEnv(java,source);
  try{
    xyRequireAdLogin();var r=XY.getVideoRewardRules();
    if(!r||Number(r.code)!==0)throw new Error(String(r&&r.message||'奖励规则获取失败'));
    var d=r.data||{},rule=d.reward_rule||{},detail=rule.rule_details||{};
    var watched=Number(d.today_watch_count||0),total=Number(detail.total_required_count||d.total_required_count||0);
    var msg='今日广告进度：'+watched+(total?'/'+total:' 次');
    var ruleName=d.rule_name||rule.rule_name||'';if(ruleName)msg+='\n规则：'+String(ruleName);
    var pending=xyPendingAd();if(pending)msg+='\n有待确认任务：'+pending;
    xySay(msg,true);
  }catch(e){xySay('奖励进度查询失败：'+String(e.message||e),true)}
}
function xyCheck(){XY.setEnv(java,source);try{XY.handshake(false);xySay(XY.token()?'会话有效，当前已登录':'协议连接正常，但尚未登录',true)}catch(e){xySay('连接检测失败：'+String(e.message||e),true)}}
function xyAutoWatchAd(){
  XY.setEnv(java,source);
  try{
    xyRequireAdLogin();
    var pending=xyPendingAd();
    if(pending){xyClearAd();xySay('检测到上次残留任务，已清理，请重新点击',true);return}
    xySay('正在自动刷广告(单次)...',false);
    var r=XY.watchAdAuto();
    if(r.success)xySay('✅ 刷广告成功\n奖励：'+r.award,true);
    else xySay('⚠️ 刷广告未成功\n'+String(r.message||'未知'),true);
  }catch(e){xySay('❌ 刷广告失败\n'+String(e.message||e),true)}
}
function xyAutoWatchAll(){
  XY.setEnv(java,source);
  try{
    xyRequireAdLogin();
    var pending=xyPendingAd();
    if(pending){xyClearAd();xySay('检测到上次残留任务，已清理，请重新点击',true);return}
    var done=XY.getTodayAdCount();
    var remaining=Math.max(0,3-done);
