      xySay('正在刷第'+cur+'/'+total+'次\n✅ 已成功'+success+'次',false);
    });
    var msg;
    if(r.total===0){
      msg='✅ 今日已成功刷3次\n无需再刷';
    }else{
      var totalDone=done+r.success;
      msg='✅ 刷广告完成\n今日共成功'+totalDone+'/3次';
      if(r.success>0)msg+='\n本次新刷成功'+r.success+'次';
      if(r.success<r.total){
        var failed=r.results.filter(function(x){return !x.success});
        if(failed.length)msg+='\n⚠️ 失败原因：'+String(failed[0].message||'');
      }
      if(totalDone>=3)msg+='\n今日额度已用完';
    }
    xySay(msg,true);
  }catch(e){xySay('❌ 自动刷广告失败\n'+String(e.message||e),true)}
}
function login(){xyLogin()}

