    display: flex;
    justify-content: space-between;
    font-size: 11px;
    color: var(--text-tertiary);
    padding-left: calc(44px + var(--s-md));
}
.timeline-info-reply {
    color: var(--text-secondary);
    margin-right: var(--s-md);
    cursor: pointer;
}
.timeline-info-other-reply {
    color: var(--accent);
    cursor: pointer;
}
.timeline-ft a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: color 0.2s ease;
}
.timeline-ft a:hover {
    color: var(--accent);
}
.reply-line {
    height: 1px;
    background: var(--border);
    margin: var(--s-lg) 0;
}
.other-timelines {
    margin-top: var(--s-md);
    padding-left: calc(44px + var(--s-md));
}
.reply-item {
    display: flex;
    flex-direction: column;
    gap: var(--s-sm);
    margin-bottom: var(--s-md);
    padding: var(--s-md);
    background: var(--bg);
    border-radius: 8px;
}
.reply-header {
    display: flex;
    align-items: center;
    gap: var(--s-md);
}
.reply-avatar {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    border: 1px solid var(--border);
    object-fit: cover;
    flex-shrink: 0;
}
.reply-user-info {
    display: flex;
    flex-direction: column;
    gap: 1px;
}
.reply-username {
    font-size: 14px;
    font-weight: 600;
    color: var(--text-primary);
}
.reply-user-title {
    font-size: 10px;
    color: var(--text-tertiary);
}
.reply-meta {
    display: flex;
    justify-content: space-between;
    font-size: 10px;
    color: var(--text-tertiary);
    margin: 0 0 var(--s-sm) calc(36px + var(--s-md));
}
.reply-content {
    font-size: 13px;
    color: var(--text-primary);
    margin-bottom: var(--s-sm);
    padding-left: calc(36px + var(--s-md));
}
.disclose {
    background: var(--bg);
    padding: var(--s-md);
    border-radius: 8px;
    margin-bottom: var(--s-md);
    display: flex;
    flex-direction: column;
    gap: var(--s-sm);
    padding-left: calc(44px + var(--s-md));
}
.disclose p {
    font-size: 13px;
    color: var(--text-secondary);
}
.disclose a {
    font-size: 13px;
    color: var(--accent);
    text-decoration: none;
    align-self: flex-start;
}
@media (max-width: 360px) {
    body { padding: var(--s-sm); }
    .timeline-avatar { width: 38px; height: 38px; }
    .reply-avatar { width: 32px; height: 32px; }
    .timeline-content, .reply-content, .disclose, .timeline-meta, .timeline-info, .reply-meta {
        padding-left: calc(38px + var(--s-sm));
    }
    .other-timelines { padding-left: calc(38px + var(--s-sm)); }
    .timeline-content { font-size: 13px; }
    .panel-body { padding: var(--s-md); }
